  ('fr-grammar-extra-06-ex-2', 'fr-grammar-extra-06', 'fr', 'B1', 'Locutions verbales et expressions courantes · exercício 2', 'Para perceber, a expressão idiomática comum é se rendre compte de.', 'Je me rends compte de mon erreur.', 'Choisissez la phrase correcte.', '["Je réalise mon erreur.","Je me rends compte de mon erreur.","Je suis besoin d''aide."]'::jsonb, 1, 1061, true),
  ('fr-grammar-extra-07-ex-1', 'fr-grammar-extra-07', 'fr', 'B2', 'Subjonctif et particularités · exercício 1', 'Il faut que seleciona subjuntivo.', 'Il faut que tu sois prêt.', 'Choisissez la phrase correcte.', '["Il faut que tu es prêt.","Il faut que tu sois prêt.","Après qu''il soit parti."]'::jsonb, 1, 1070, true),
